// Files generated by scripts/convert.mjs must be ignored by git and by the `npm start` watcher;
// a generated file the watcher saw would trigger a rebuild after every rebuild.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { test } from 'node:test';
import * as app from '../../src/config/app.mjs';

const read = (rel) => fs.readFileSync(new URL(rel, import.meta.url), 'utf8');

test('every file the converter writes under site/ is listed in GENERATED_PATHS', () => {
  const written = [...read('../../scripts/convert.mjs').matchAll(/write\(path\.join\(SITE, ([A-Z_]+)\)/g)].map((m) => m[1]);
  assert.ok(written.length > 0, 'the converter writes generated files');
  const listed = (p) => app.GENERATED_PATHS.some((g) => p === g || p.startsWith(`${g}/`));
  for (const name of [...written, 'DOCS_DIR']) assert.ok(listed(app[name]), `${name} is listed`);
});

test('the watcher of `npm start` skips GENERATED_PATHS', () => {
  assert.match(read('../../scripts/serve.mjs'), /GENERATED_PATHS\.map\(/);
});

test('every generated path is ignored by git', () => {
  const ignored = read('../../../.gitignore').split('\n');
  for (const p of app.GENERATED_PATHS) assert.ok(ignored.includes(`site/${p}/`) || ignored.includes(`site/${p}`), `${p} is in .gitignore`);
});
